/** Existing host RAF only. Hold exact prepared effects, NEVER an old camera/actor frame. */
export function createClockConsumer({waterCache,render}){
 let closed=false,inFlight=null,lastRenderedMs=null,effectMs=null,latestPreparedMs=null,heldEffectUpdates=0,preparations=0,lastError=null;
 const check=()=>{if(closed)throw Error('WETLAND_CLOCK_CONSUMER_CLOSED')};
 function request(ms){check();if(inFlight)return inFlight;preparations++;inFlight=waterCache.advance(ms).then(result=>{check();if(!Number.isFinite(result?.preparedMs)||!waterCache.isPrepared(result.preparedMs))throw Error('WETLAND_PREPARED_CLOCK');latestPreparedMs=result.preparedMs;return result}).catch(e=>{lastError=e;throw e}).finally(()=>{inFlight=null});inFlight.catch(()=>{});return inFlight}
 return Object.freeze({async prime(ms){check();if(!Number.isFinite(ms))throw Error('WETLAND_CLOCK');await request(ms);check();waterCache.pin(ms);effectMs=ms;await request(ms+50);check();if(!waterCache.isPrepared(ms))throw Error('WETLAND_INITIAL_PHASE');},frame(options){check();const ms=options?.ms;if(!Number.isFinite(ms))throw Error('WETLAND_CLOCK');if(lastError)throw lastError;if(effectMs===null)throw Error('WETLAND_NOT_PRIMED');const ready=waterCache.isPrepared(ms);if(ready){waterCache.pin(ms);effectMs=ms}else{heldEffectUpdates++;if(latestPreparedMs!==null&&latestPreparedMs>effectMs&&latestPreparedMs<=ms&&waterCache.isPrepared(latestPreparedMs)){waterCache.pin(latestPreparedMs);effectMs=latestPreparedMs}}const output=render({...options,ms:effectMs});lastRenderedMs=ms;if(!inFlight){if(!ready)request(ms);else if(!waterCache.isPrepared(ms+50))request(ms+50)}return{...output,skipped:false,heldEffect:!ready,requestedMs:ms,presentationMs:ms,effectMs,exactRequestedPhase:ready}},stats(){return{lastRenderedMs,effectMs,latestPreparedMs,heldEffectUpdates,skippedUpdates:heldEffectUpdates,preparations,inFlight:!!inFlight,pendingQueueLength:0,lastError:lastError?.message??null}},async settled(){if(inFlight)await inFlight;check()},dispose(){if(closed)return;closed=true;waterCache.dispose();render=null;lastError=null;effectMs=null;latestPreparedMs=null;}})
}
